UPDATE disposals
SET disposal_type          = #{disposalType},
    disposal_reason        = #{disposalReason},
    disposal_detail_reason = #{disposalDetailReason}
WHERE disposal_id = #{disposalId}
  AND disposal_status = '요청'

mapper.select:
SELECT d.disposal_req_at AS disposalReqAt, s.store_name AS storeName, i.ingredient_name AS ingredientName, d.disposal_quantity AS disposalQuantity, d.disposal_price AS disposalPrice, d.disposal_type AS disposalType, d.processing_method AS processingMethod, d.disposal_status AS disposalStatus, dai.check_at AS checkAt FROM disposals d LEFT OUTER JOIN order_details AS od ON d.order_detail_id = od.order_detail_id LEFT OUTER JOIN ingredients i ON od.ingredient_id = i.ingredient_id LEFT OUTER JOIN orders AS o ON od.order_id = o.order_id LEFT OUTER JOIN stores s ON o.store_id = s.store_id LEFT OUTER JOIN disposal_app_infos dai ON dai.disposal_id = d.disposal_id
AND s.user_id = #{userId}
AND s.store_name LIKE CONCAT('%', #{storeName}, '%')
AND i.ingredient_name LIKE CONCAT('%', #{ingredientName}, '%')
AND d.disposal_status = #{disposalStatus}
AND d.disposal_req_at >= #{startDate} AND d.disposal_req_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND d.disposal_type = #{disposalType}
AND d.processing_method = #{processingMethod}
ORDER BY d.disposal_req_at
DESC
ASC

